// Send gate for the assistant's push notifications.
//
// Policy (promo only):
//   - at most 3 promos per customer per local calendar day (midnight to midnight
//     in the customer's own time zone)
//   - at least 2 hours between two promos to the same customer
// Security pushes are never limited and never counted: they are transactional.
//
// request() allowed means the caller sends now, so the send is recorded at once.
// cancel(id) removes that record when the push never left the system.

import { randomUUID } from 'node:crypto';

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;
// Records older than this can no longer affect a decision: a local day is at
// most 24 hours long (25 on a DST change), and the gap rule needs 2 hours.
const RETAIN_MS = 48 * 60 * 60 * 1000;

export const RULES = Object.freeze({
  DAILY_CAP: 'daily-cap',
  MIN_GAP: 'min-gap',
  INVALID_CATEGORY: 'invalid-category',
  INVALID_TIME_ZONE: 'invalid-time-zone',
  INVALID_TIME: 'invalid-time',
  INVALID_USER: 'invalid-user',
});

const formatters = new Map();

// Local calendar date ("2026-10-23") of an instant in the given IANA zone.
// Throws RangeError for an unknown zone.
function localDay(timeZone, ms) {
  let fmt = formatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, fmt);
  }
  return fmt.format(ms);
}

export function createGate() {
  // userId -> array of { id, t } for allowed promos not cancelled
  const promosByUser = new Map();
  // id -> { userId, record } for allowed promos, so cancel(id) can find them
  const promosById = new Map();

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function request({ userId, timeZone, category, now } = {}) {
    if (category === 'security') {
      return { allowed: true, rule: '', id: randomUUID() };
    }
    if (category !== 'promo') return deny(RULES.INVALID_CATEGORY);
    if (typeof userId !== 'string' || userId === '') return deny(RULES.INVALID_USER);

    const t = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(t)) return deny(RULES.INVALID_TIME);

    let today;
    try {
      today = localDay(timeZone, t);
    } catch {
      return deny(RULES.INVALID_TIME_ZONE);
    }

    let list = promosByUser.get(userId);
    if (list) {
      const kept = list.filter((r) => {
        if (r.t >= t - RETAIN_MS) return true;
        promosById.delete(r.id);
        return false;
      });
      if (kept.length !== list.length) {
        list = kept;
        if (kept.length) promosByUser.set(userId, kept);
        else promosByUser.delete(userId);
      }
    }
    list = list ?? [];

    // The day is judged in the zone of this request.
    const sentToday = list.filter((r) => localDay(timeZone, r.t) === today).length;
    if (sentToday >= MAX_PROMOS_PER_DAY) return deny(RULES.DAILY_CAP);

    if (list.some((r) => Math.abs(t - r.t) < MIN_GAP_MS)) return deny(RULES.MIN_GAP);

    const record = { id: randomUUID(), t };
    list.push(record);
    promosByUser.set(userId, list);
    promosById.set(record.id, { userId, record });
    return { allowed: true, rule: '', id: record.id };
  }

  function cancel(id) {
    const entry = promosById.get(id);
    if (!entry) return; // unknown, security, already cancelled or pruned
    promosById.delete(id);
    const list = promosByUser.get(entry.userId);
    if (!list) return;
    const rest = list.filter((r) => r !== entry.record);
    if (rest.length) promosByUser.set(entry.userId, rest);
    else promosByUser.delete(entry.userId);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-inv-d2-2/bot.mjs';

const LA = 'America/Los_Angeles';
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });
const d = (s) => new Date(s);

// LA is UTC-7 in October: local midnight = 07:00Z.
{
  const g = createGate();
  const a = req(g, { now: d('2026-10-23T07:00:00Z') });
  assert.equal(a.allowed, true); assert.equal(a.rule, ''); assert.ok(a.id);
  // 1h59m later: gap
  let r = req(g, { now: d('2026-10-23T08:59:00Z') });
  assert.deepEqual(r, { allowed: false, rule: 'min-gap', id: null });
  // exactly 2h: ok
  assert.equal(req(g, { now: d('2026-10-23T09:00:00Z') }).allowed, true);
  assert.equal(req(g, { now: d('2026-10-23T11:00:00Z') }).allowed, true);
  // 4th same local day
  r = req(g, { now: d('2026-10-23T20:00:00Z') });
  assert.equal(r.rule, 'daily-cap');
  // 06:59Z next UTC... still same LA day (till 07:00Z Oct 24)
  assert.equal(req(g, { now: d('2026-10-24T06:59:00Z') }).rule, 'daily-cap');
  // new local day, gap satisfied
  assert.equal(req(g, { now: d('2026-10-24T07:00:00Z') }).allowed, true);
}
// Day is local, not UTC: 3 promos before UTC midnight, 1 after, same LA day.
{
  const g = createGate();
  for (const t of ['2026-10-23T20:00:00Z', '2026-10-23T22:00:00Z', '2026-10-24T00:00:00Z'])
    assert.equal(req(g, { now: d(t) }).allowed, true);
  assert.equal(req(g, { now: d('2026-10-24T02:00:00Z') }).rule, 'daily-cap');
}
// Gap spans local midnight.
{
  const g = createGate();
  assert.equal(req(g, { now: d('2026-10-24T06:30:00Z') }).allowed, true);
  assert.equal(req(g, { now: d('2026-10-24T07:30:00Z') }).rule, 'min-gap');
}
// Cancel frees both cap and gap; double cancel and unknown are harmless.
{
  const g = createGate();
  const a = req(g, { now: d('2026-10-23T15:00:00Z') });
  g.cancel(a.id); g.cancel(a.id); g.cancel('nope'); g.cancel(undefined);
  assert.equal(req(g, { now: d('2026-10-23T15:01:00Z') }).allowed, true);
  const ids = [];
  ids.push(req(g, { now: d('2026-10-23T17:01:00Z') }).id);
  const x = req(g, { now: d('2026-10-23T19:01:00Z') });
  assert.equal(req(g, { now: d('2026-10-23T21:01:00Z') }).rule, 'daily-cap');
  g.cancel(x.id);
  assert.equal(req(g, { now: d('2026-10-23T21:01:00Z') }).allowed, true);
}
// Users independent; zones independent (Berlin vs LA).
{
  const g = createGate();
  assert.equal(g.request({ userId: 'a', timeZone: 'Europe/Berlin', category: 'promo', now: d('2026-10-23T10:00:00Z') }).allowed, true);
  assert.equal(g.request({ userId: 'b', timeZone: 'Europe/Berlin', category: 'promo', now: d('2026-10-23T10:00:00Z') }).allowed, true);
  // Berlin (UTC+2): 21:30Z Oct 23 = 23:30 local; 22:30Z = 00:30 next day
  const h = createGate();
  const B = (t) => h.request({ userId: 'a', timeZone: 'Europe/Berlin', category: 'promo', now: d(t) });
  assert.ok(B('2026-10-23T18:00:00Z').allowed && B('2026-10-23T20:00:00Z').allowed && B('2026-10-23T22:00:00Z').allowed);
  assert.equal(B('2026-10-23T22:00:00Z').rule, 'min-gap'.replace('min-gap', 'daily-cap')); // 00:00 Oct 24 local? 22:00Z=00:00+1 -> new day
}

