cd /tmp/gate-check && python3 - <<'EOF'
p='check.mjs'
s=open(p).read()
i=s.index("  // Berlin (UTC+2)")
s=s[:i]+"""  // Berlin is UTC+2: 18:00Z and 20:00Z are Oct 23 local, 22:00Z is Oct 24 local.
  const h = createGate();
  const B = (t) => h.request({ userId: 'a', timeZone: 'Europe/Berlin', category: 'promo', now: d(t) });
  assert.ok(B('2026-10-23T14:00:00Z').allowed && B('2026-10-23T16:00:00Z').allowed && B('2026-10-23T18:00:00Z').allowed);
  assert.equal(B('2026-10-23T20:00:00Z').rule, 'daily-cap'); // 22:00 local, 4th
  assert.equal(B('2026-10-23T22:00:00Z').allowed, true);     // 00:00 local, new day
}
// Security: never limited, never counted, unique ids, cancel harmless.
{
  const g = createGate();
  const t = d('2026-10-23T15:00:00Z');
  const ids = new Set();
  for (let i = 0; i < 10; i++) {
    const r = g.request({ userId: 'u', timeZone: LA, category: 'security', now: t });
    assert.ok(r.allowed && r.rule === '' && r.id); ids.add(r.id);
  }
  assert.equal(ids.size, 10);
  g.cancel([...ids][0]);
  assert.equal(req(g, { now: t }).allowed, true); // promo unaffected
  assert.equal(g.request({ userId: 'u', timeZone: LA, category: 'security', now: t }).allowed, true);
}
// Bad input denied with distinct rules, not thrown.
{
  const g = createGate();
  assert.equal(req(g, { timeZone: 'Mars/Base', now: d('2026-10-23T15:00:00Z') }).rule, 'invalid-time-zone');
  assert.equal(req(g, { now: new Date('x') }).rule, 'invalid-time');
  assert.equal(req(g, { category: 'spam', now: d('2026-10-23T15:00:00Z') }).rule, 'invalid-category');
  assert.equal(req(g, { now: d('2026-10-23T15:00:00Z') }).allowed, true); // failed ones recorded nothing
}
// DST: Berlin fall-back 2026-10-25 (25h day). Local day is still one date.
{
  const g = createGate();
  const B = (t) => g.request({ userId: 'a', timeZone: 'Europe/Berlin', category: 'promo', now: d(t) });
  // 22:00Z Oct 24 = 00:00 local Oct 25 (+2); day ends 23:00Z Oct 25 (+1 after change)
  assert.ok(B('2026-10-24T22:00:00Z').allowed && B('2026-10-25T00:00:00Z').allowed && B('2026-10-25T02:00:00Z').allowed);
  assert.equal(B('2026-10-25T22:30:00Z').rule, 'daily-cap'); // 23:30 local Oct 25
  assert.equal(B('2026-10-25T23:00:00Z').allowed, true);     // 00:00 local Oct 26
}
console.log('all checks passed');
"""
open(p,'w').write(s)
EOF
